    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0x91BA885546DF2B0BULL + 0xBFFD3D165A6ADF4EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xDFBD442F03D74A35ULL + 0xA441D8DA8DA01B49ULL);
