            //
            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFireLaneD[((aIndex + 6639U)) & S_BLOCK1], 53U) ^ RotL64(aFireLaneB[((aIndex + 4942U)) & S_BLOCK1], 29U));
