            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 7300U)) & S_BLOCK1], 27U) ^ RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 5241U)) & S_BLOCK1], 53U));
