            //
            aOrbiterB = ((aWandererC + RotL64(aCross, 37U)) + 0x27A209647BEB99BAULL) + aSeedOrbiterAssignSaltD[(((255U - aIndex) + 208U)) & S_SALT1];
            aOrbiterE = (((aWandererJ + RotL64(aScatter, 29U)) + RotL64(aCarry, 21U)) + 0x3A6EA88E7CC2C388ULL) + aNonceWordK;
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 13U)) + 0xBB71641E91663407ULL) + aNonceWordA;
            aOrbiterI = (((aWandererK + RotL64(aPrevious, 4U)) + RotL64(aCarry, 41U)) + 0x6BC363580D81EEFBULL) + aNonceWordL;
            aOrbiterF = ((aWandererA + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0xA8EFD4A912DC0A5AULL;
            aOrbiterA = ((aWandererI + RotL64(aCross, 21U)) + 0xC086317CA4EB39BCULL) + aNonceWordB;
