            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x89708BD0EA2D6C69ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0xC63E687C1F4EF1ADULL) ^ aSeedOrbiterUpdateSaltE[((aIndex + 231U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x8567DE38A6859957ULL), 3U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0xFDCAA69E95037686ULL) + aNonceWordM;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xD63A33023B2EE1D6ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x012E717E87A7936FULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x7CA17A242FE18106ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x179F1A2DED2D729FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7CE05FA1680CED4FULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x33B332E51C203E3AULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x28129A3B66033354ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA2287A5296C4D647ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xA133C72A6C1D878AULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x335042FE5BC9F967ULL) ^ aSeedOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x35F69E85532FC5BDULL), 11U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0xF2F035B37268BC40ULL) + aNonceWordJ;
