            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x767EF304D457BCA4ULL) + aSeedOrbiterUpdateSaltA[((aIndex + 169U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x3F348E473FBC10BDULL) ^ aSeedOrbiterUpdateSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x66BFA4F9060E165BULL), 57U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterE, 13U);
            aIngress = aIngress + (RotL64(aOrbiterB, 27U) ^ aOrbiterH);
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterJ, 19U));
            aIngress = aIngress + RotL64(aOrbiterF, 34U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aIngress, 35U) + aOrbiterI) + RotL64(aOrbiterB, 13U));
            aWandererC = aWandererC + ((RotL64(aCross, 51U) + aOrbiterA) + RotL64(aOrbiterE, 29U));
            aWandererI = aWandererI ^ (((RotL64(aScatter, 60U) + aOrbiterJ) + RotL64(aOrbiterI, 53U)) + aNonceWordE);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 41U) + RotL64(aOrbiterB, 23U)) + aOrbiterA) + RotL64(aCarry, 47U)) + aSeedWandererUpdateSaltA[((aIndex + 254U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 13U) + aOrbiterE) + RotL64(aOrbiterH, 3U)) + aNonceWordP);
            aWandererJ = aWandererJ + ((((RotL64(aCross, 3U) + aOrbiterF) + RotL64(aOrbiterI, 60U)) + RotL64(aCarry, 11U)) + aNonceWordG);
            aWandererK = aWandererK ^ ((((RotL64(aPrevious, 21U) + RotL64(aOrbiterI, 47U)) + aOrbiterA) + aNonceWordH) + aSeedWandererUpdateSaltF[(((255U - aIndex) + 140U)) & S_SALT1]);
