            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 12781U)) & S_BLOCK1], 47U) ^ RotL64(aFireLaneC[((aIndex + 14783U)) & S_BLOCK1], 57U));
            aIngress ^= (RotL64(aAetherLaneD[((aIndex + 9897U)) & S_BLOCK1], 29U) ^ RotL64(aAetherLaneC[((S_BLOCK1 - aIndex + 10057U)) & S_BLOCK1], 6U));
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aSeedDomainWordIngress) ^ aNonceWordI));
            //
            aCross = (RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 10855U)) & S_BLOCK1], 39U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 10617U)) & S_BLOCK1], 19U));
            aCross ^= (RotL64(aAetherLaneB[((S_BLOCK1 - aIndex + 16172U)) & S_BLOCK1], 4U) ^ RotL64(aVaporLaneD[((S_BLOCK1 - aIndex + 15592U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB(((aCross ^ aSeedDomainWordCross) ^ aNonceWordO));
            //
            aScatter = (RotL64(aIngress, 3U) + RotL64(aCarry, 19U)) ^ (RotL64(aPrevious, 37U) + RotL64(aCross, 54U));
            aScatter = TwistMix64::DiffuseC(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordG));
            //
            aOrbiterD = ((aWandererG + RotL64(aScatter, 35U)) + 0xD8904A4D5744B454ULL) + aSeedOrbiterAssignSaltE[(((255U - aIndex) + 225U)) & S_SALT1];
            aOrbiterG = (((aWandererB + RotL64(aIngress, 13U)) + RotL64(aCarry, 27U)) + 0xD319CD918A863021ULL) + aNonceWordE;
            aOrbiterF = ((aWandererC + RotL64(aPrevious, 43U)) + 0x4FAF5F1584D25E5EULL) + aSeedOrbiterAssignSaltF[(((255U - aIndex) + 226U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aCross, 21U)) + RotL64(aCarry, 57U)) + 0xF2105918A1D0E862ULL;
            aOrbiterI = ((aWandererJ + RotL64(aScatter, 5U)) + RotL64(aCarry, 43U)) + 0x34E1DF102628E7B5ULL;
            aOrbiterH = ((aWandererD + RotL64(aCross, 56U)) + 0x6CD26814F9E61724ULL) + aNonceWordN;
            aOrbiterE = (aWandererH + RotL64(aPrevious, 29U)) + 0x8DB9099456BAD310ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x78C4B0A0EC4A8955ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x29C437741C0C45F1ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6FB33919C616EADFULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x6276B41A6390E357ULL;
            aOrbiterI = (((aOrbiterI ^ aOrbiterF) ^ 0xD35E82307B728222ULL) ^ aSeedOrbiterUpdateSaltE[((aIndex + 168U)) & S_SALT1]) ^ aNonceWordB;
            aOrbiterI = RotL64((aOrbiterI * 0x4423979DCC054E19ULL), 41U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0x8F66A8557570E4FEULL) + aSeedOrbiterUpdateSaltB[((aIndex + 161U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x4D349C24EFB11511ULL) ^ aNonceWordM;
            aOrbiterD = RotL64((aOrbiterD * 0x3385CF4E62625689ULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x2F5953944AEA44A1ULL) + aSeedOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0x02D5E4A97161217DULL) ^ aNonceWordC;
            aOrbiterG = RotL64((aOrbiterG * 0xC6045B615CA82EE5ULL), 21U);
            //
            aOrbiterI = (((aOrbiterI + aOrbiterD) + 0x38C91C1FCB721758ULL) + aSeedOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1]) + aNonceWordH;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xD8B2856C7389FC5EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x146ABAC52239F0D5ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xD6F8CEB9A6AD20BBULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x76C5F51415B94381ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xF2EA4A816BCA7421ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xCBA2A1E1432CC0C3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x4DF85114F9E73F78ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8456D4B14DAEE219ULL), 53U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterI, 19U);
            aIngress = aIngress + (RotL64(aOrbiterE, 54U) ^ aOrbiterH);
            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterK, 27U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ ((RotL64(aCross, 27U) + RotL64(aOrbiterI, 27U)) + aOrbiterE);
            aWandererE = aWandererE + (((RotL64(aScatter, 47U) + RotL64(aOrbiterG, 35U)) + aOrbiterH) + RotL64(aCarry, 53U));
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 38U) + RotL64(aOrbiterH, 20U)) + aOrbiterE);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 5U) + RotL64(aOrbiterD, 47U)) + aOrbiterH) + RotL64(aCarry, 3U)) + aNonceWordK);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 19U) + aOrbiterK) + RotL64(aOrbiterD, 13U)) + aSeedWandererUpdateSaltB[((aIndex + 222U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aPrevious, 11U) + aOrbiterI) + RotL64(aOrbiterF, 5U)) + aSeedWandererUpdateSaltE[(((255U - aIndex) + 253U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aCross, 53U) + aOrbiterK) + RotL64(aOrbiterF, 57U)) + aNonceWordG);
            //
            aCarry = aCarry + (RotL64(aWandererE, 5U) ^ aWandererD);
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererH, 53U));
