            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 3U)) + RotL64(aCarry, 13U)) + 0x39665DF720C4E5E6ULL;
            aOrbiterA = ((aWandererD + RotL64(aIngress, 14U)) + RotL64(aCarry, 3U)) + 0xDB43EF24D94A320DULL;
