    const std::uint64_t &aTwistDomainWordScatter = pWorkSpace->mDomainBundle.mTwistConstants.mScatter;
    const std::uint64_t &aTwistDomainWordCross = pWorkSpace->mDomainBundle.mTwistConstants.mCross;
