            aOrbiterH = ((aWandererI + RotL64(aCross, 23U)) + RotL64(aCarry, 47U)) + 0xF9617A12F227C51DULL;
            aOrbiterK = (aWandererK + RotL64(aPrevious, 27U)) + 0x7D67BBAF9552527AULL;
            aOrbiterA = ((aWandererF + RotL64(aIngress, 42U)) + RotL64(aCarry, 39U)) + 0x57ACD5DCEEB1F410ULL;
            aOrbiterC = (aWandererJ + RotL64(aPrevious, 19U)) + 0xAACCE2E059B30EBBULL;
