            aWandererE = aWandererE ^ ((RotL64(aScatter, 51U) + aOrbiterI) + RotL64(aOrbiterH, 47U));
            aWandererB = aWandererB + (((RotL64(aCross, 27U) + RotL64(aOrbiterE, 19U)) + aOrbiterC) + RotL64(aCarry, 35U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 37U) + RotL64(aOrbiterI, 23U)) + aOrbiterC) + aTwistWandererUpdateSaltE[(((255U - aIndex) + 35U)) & S_SALT1]);
