            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x40C524F87E24DE9AULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 225U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x8431D764DB979B7AULL;
