            aOrbiterD = RotL64((aOrbiterD * 0xE421A28FD81F8AD9ULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x2688FBCF1AC18193ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xB4E7C39C864E5E0DULL;
