            aWandererC = aWandererC ^ (((RotL64(aIngress, 57U) + aOrbiterJ) + RotL64(aOrbiterF, 5U)) + aKeyRotateBWandererUpdateSaltD[((aIndex + 27U)) & S_SALT1]);
