            aOrbiterE = ((aWandererC + RotL64(aScatter, 11U)) + 0xAEF938319E8BD7B9ULL) + aKeyRotateBOrbiterAssignSaltA[((aIndex + 45U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x15A377F7A8483A9DULL;
