            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0x937BACBC383AA182ULL) + aKeyRotateBOrbiterUpdateSaltA[((aIndex + 89U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x1AC60F3982EE350CULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0319659EF4D812BFULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xF49E74EF63F0BDB7ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x34707A551215A95FULL;
            aOrbiterE = RotL64((aOrbiterE * 0x51596B850AA1C375ULL), 23U);
